package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.features.access.trustedclient.domain.AllowedAudiences;

class AllowedAudiencesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property allowed audiences of trusted client ")
  void test_allowed_audiences_v_o_builder() {
    Assertions.assertTrue(AllowedAudiencesVO.tryFrom(null).getAllowedAudiences().isEmpty());
    List<AllowedAudiences> list = List.of();
    Assertions.assertEquals(list, AllowedAudiencesVO.from(list).getAllowedAudiences());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AllowedAudiencesVO.tryFrom(falingInstance));
    Assertions.assertEquals(
        "[" + List.of(AllowedAudiences.builder().uid("one").audience("one").version(1).build())
            + "]",
        AllowedAudiencesVO
            .from(List.of(AllowedAudiences.builder().uid("one").audience("one").version(1).build()))
            .toString());
  }
}
